var binary = Uint8Array.from(
  atob(
    "",
  ),
  (c) => c.charCodeAt(0),
);

const wasmBinaryPromise = new Response(
  new Blob([binary]).stream().pipeThrough(new DecompressionStream("gzip")),
).bytes();

const getWasmInstance = async (info?: WebAssembly.Imports) => {
  return WebAssembly.instantiate(await wasmBinaryPromise, info).then(
    (wasm) => wasm.instance.exports,
  );
};

export { getWasmInstance };
